{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "s3:GetObject",
        "s3:ListBucket"
      ],
      "Resource": [
        "arn:aws:s3:::my-app-bucket",
        "arn:aws:s3:::my-app-bucket/*"
      ]
    }
  ]
}

// ARN format: arn:partition:service:region:account-id:resource
// arn:aws:s3:::my-app-bucket  ← S3 bucket (no region/account — S3 is global)
// arn:aws:s3:::my-app-bucket/* ← all objects INSIDE the bucket
// Both lines needed: one for the bucket itself, one for objects inside

// Common actions:
// s3:GetObject, s3:PutObject, s3:DeleteObject, s3:ListBucket
// ec2:DescribeInstances, ec2:StartInstances, ec2:StopInstances
// lambda:InvokeFunction
// rds:DescribeDBInstances
// Use '*' for all actions (only for admin roles)

// 1. Create a role with a Trust Policy (who can assume this role):
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Principal": { "Service": "ec2.amazonaws.com" },
    "Action": "sts:AssumeRole"
  }]
}
// This says: EC2 instances can assume this role

// 2. Attach a Permission Policy (what they can do):
{
  "Statement": [{
    "Effect": "Allow",
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::my-bucket/*"
  }]
}

// 3. Attach the role to the EC2 instance at launch

// 4. In your application code — NO credentials needed:
import { S3Client, GetObjectCommand } from '@aws-sdk/client-s3';
// SDK automatically uses the EC2 instance role credentials
const s3 = new S3Client({ region: 'us-east-1' });
const result = await s3.send(new GetObjectCommand({ Bucket: 'my-bucket', Key: 'file.txt' }));

// The SDK fetches temporary credentials from the EC2 metadata service
// (http://169.254.169.254/latest/meta-data/iam/security-credentials/)
// They auto-rotate every hour — no manual secret management needed
